 const name=selectedServer;if(!name)return;const seq=++outlineSeq;outlineServer=name;outlineBusy=true;clearOutlineSecrets();$('#outline-keys').replaceChildren();$('#outline-status').textContent=name+' · 키 조회 중';$('#refresh-outline').disabled=true;$('#save-outline').disabled=true;
