 event.preventDefault();const name=selectedServer;if(!name||outlineBusy)return;const seq=++outlineSeq;outlineBusy=true;$('#save-outline').disabled=true;$('#save-outline').textContent='저장 중';$('#refresh-outline').disabled=true;$('#outline-save-status').textContent='연결 정보를 암호화 저장하고 있습니다';
