async function server(){snapshot=await api('/api/admin/simulation');const state=snapshot.state;$('#attached-ip').textContent=state.attachedIp;$('#dns-ip').textContent=state.dnsIp;const next=state.attachedIp===state.candidateIp?Number(state.attachedIp.split('.').at(-1))+10:null;$('#candidate-ip').textContent=state.status==='needs-review'?state.candidateIp:next?(next>250?'시험 범위 소진':`192.0.2.${next}`):state.candidateIp;$('#server-state').textContent=labels[state.status]??state.status;$('#review-note').hidden=state.status!=='needs-review';$('#history').replaceChildren(...snapshot.jobs.map(job=>{const details=document.createElement('details');details.className='history-item';const summary=document.createElement('summary');summary.textContent=`${new Date(job.createdAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})} · ${job.actor} · ${labels[job.result.status]??job.result.status}`;const p=document.createElement('p');p.textContent=`IP ${job.result.originalIp} → ${job.result.attachedIp} / DNS ${job.result.dnsIp}`;const ol=document.createElement('ol');job.result.logs.forEach(line=>{const li=document.createElement('li');li.textContent=line;ol.append(li);});details.append(summary,p,ol);return details;}));controls();}
