const readErrors={'permission-denied':'조회 권한 부족','authentication-required':'AWS 로그인·프로필 확인 필요','not-found':'해당 계정에서 영역을 찾지 못함',timeout:'조회 시간 초과','query-failed':'조회 실패'};
