let selectedServer=null,fleetServers=[],fleetLoaded=false,fleetLoading=false,liveJobs=[],liveJobsLoaded=false,serverDetailView='overview',fleetLoadSeq=0,liveLoadSeq=0,liveDetailSeq=0;
