const healthReasons={'timeout':'4초 내 응답 없음','connection-refused':'서버가 연결을 거부함','network-unreachable':'점검 서버의 네트워크 경로 확인 필요','probe-permission-denied':'점검 서버의 연결 권한 확인 필요','connection-failed':'TCP 연결 실패','port-not-configured':'서버별 서비스 포트 설정 필요','instance-unverified':'AWS 인증·서버 조회 확인 필요','instance-not-running':'서버가 실행 상태가 아님','invalid-target':'검증 가능한 공인 IPv4가 없음'};
function serviceView(server){const name=server.instanceName,report=healthReports.get(name);if(healthBusy.has(name))return {label:'점검 중',kind:'neutral'};if(healthErrors.has(name))return {label:'확인 필요',kind:'warn'};if(!report)return {label:'미점검',kind:'neutral'};if(report.publicIp!==server.instance?.data?.publicIp||report.server.state!==server.instance?.data?.state||Date.now()-Date.parse(report.finishedAt)>60000)return {label:'재점검 필요',kind:'neutral'};return {label:report.tcp.status==='connected'?'연결 성공':report.tcp.status==='failed'?'연결 실패':report.tcp.reason==='port-not-configured'?'포트 미설정':'미확인',kind:report.tcp.status==='connected'?'ok':report.tcp.status==='failed'?'warn':'neutral'};}
function healthControls(){$('#check-server-health').disabled=!selectedServer||liveBusy||healthBusy.has(selectedServer);$('#check-server-health').textContent=healthBusy.has(selectedServer)?'점검 중…':'상태 점검';}
function renderHealth(s){const box=$('#server-health-result'),report=healthReports.get(s.instanceName);box.replaceChildren();if(healthErrors.has(s.instanceName)){const note=document.createElement('p');note.className='attention-note';note.textContent='점검 요청 실패 · '+healthErrors.get(s.instanceName);box.append(note);}if(!report){const p=document.createElement('p');p.className='fine';p.textContent='상태 점검을 누르면 선택한 서버의 실행·TCP·DNS를 확인합니다';box.append(p);return;}
 const service=serviceView(s);box.append(readTable('최근 상태 점검',[['서버 실행',report.server.status==='running'?'실행 중':report.server.status==='not-running'?'실행 중 아님':'미확인'],['TCP 서비스',service.label+(report.servicePort?' · '+report.servicePort:'')],['점검 IP',report.publicIp],['DNS 주소 비교',report.dns.status==='match'?'일치':report.dns.status==='mismatch'?'불일치':'미확인'],['DNS 관리 영역',report.dns.authorityMatched?'공개 NS와 일치':'미확인'],['점검 완료',dateText(report.finishedAt)],['TCP 응답 시간',report.tcp.latencyMs===undefined?'—':report.tcp.latencyMs+' ms']]));if(report.tcp.reason){const p=document.createElement('p');p.className=report.tcp.status==='failed'?'attention-note':'fine';p.textContent=healthReasons[report.tcp.reason]??'점검 대상과 설정을 확인해 주세요';box.append(p);}const hint=document.createElement('p');hint.className='fine';hint.textContent='관리자 서버에서 연결한 시점의 결과입니다 · 최대 10초 캐시 · 1분 경과 또는 IP/실행 상태 변경 시 재점검 필요';box.append(hint);}
async function checkSelectedServer(){const name=selectedServer,epoch=healthEpoch;if(!name||healthBusy.has(name)||liveBusy)return;healthBusy.add(name);healthErrors.delete(name);healthControls();renderFleet();try{const report=await api('/api/admin/servers/'+encodeURIComponent(name)+'/health');if(!csrf||epoch!==healthEpoch)return;if(report.instanceName!==name)throw Error('점검 대상이 일치하지 않습니다');healthReports.set(name,report);healthExpired.delete(name);const index=fleetServers.findIndex(s=>s.instanceName===name);if(index>=0&&Date.parse(report.infrastructure.observedAt)>=Date.parse(fleetServers[index].observedAt))fleetServers[index]=report.infrastructure;}catch(error){if(csrf&&epoch===healthEpoch)healthErrors.set(name,error.message);}finally{if(epoch===healthEpoch){healthBusy.delete(name);renderFleet();const current=fleetServers.find(s=>s.instanceName===selectedServer);if(current)infrastructureDetail(current);healthControls();}}}
$('#check-server-health').onclick=checkSelectedServer;
setInterval(()=>{if(!csrf||$('#server-management').hidden)return;let changed=false;for(const [name,report] of healthReports){if(Date.now()-Date.parse(report.finishedAt)>60000&&!healthExpired.has(name)){healthExpired.add(name);changed=true;}}if(changed){renderFleet();const s=fleetServers.find(s=>s.instanceName===selectedServer);if(s)infrastructureDetail(s);}},10000);
const stepNames={allocate:'새 IP 확보',detach:'기존 IP 분리',attach:'새 IP 연결',service:'서비스 확인',dns:'DNS 갱신',verify:'DNS 전파·접속 확인',old_ip_cleanup:'기존 IP 정리',release:'기존 IP 반환'};
