function kstInput(date=new Date()){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(date).replace(' ','T');}
const inputTime=value=>value?new Date(value+':00+09:00').toISOString():null;
function closeCustomerDrawer(){selectedCustomer=null;customerLoadSeq++;paymentRequestKey=null;refundRequestKey=null;if($('#customer-detail').open)$('#customer-detail').close();}
