async function loadCustomer(id){const seq=++customerLoadSeq,data=await api('/api/admin/customers/'+encodeURIComponent(id));if(!csrf||seq!==customerLoadSeq)return;selectedCustomer=data.customer;paymentRequestKey=null;refundRequestKey=null;const c=selectedCustomer;$('#customer-detail-notice').textContent='';if(!$('#customer-detail').open)$('#customer-detail').showModal();$('#customer-detail-title').textContent=c.displayName+' · 고객 상세';$('#customer-detail-facts').replaceChildren(readTable('이용 정보',[['이메일',c.email],['표시 상태',customerStatuses[c.status]],['요금제',planNames[c.planCode]??'미설정'],['서버·키',(c.serverId??'미할당')+' / '+(c.keyId??'미할당')],['시작·만료',dateText(c.startsAt)+' → '+dateText(c.expiresAt)],['남은 기간',c.remainingDays===null?'미설정':c.remainingDays+'일 · 24시간 단위 올림']]));const form=$('#profile-form');form.elements.planCode.value=c.planCode??'';form.elements.status.value=c.storedStatus;form.elements.startsAt.value=c.startsAt?kstInput(new Date(c.startsAt)):'';form.elements.expiresAt.value=c.expiresAt?kstInput(new Date(c.expiresAt)):'';form.elements.note.value=c.note;
$('#payment-rows').replaceChildren(...data.payments.map(p=>{const tr=document.createElement('tr');const state=p.status==='paid'?(p.refunded===p.amount?'전액 환불':p.refunded?'부분 환불':'결제 완료'):({pending:'대기',failed:'실패',cancelled:'취소'}[p.status]??p.status);for(const v of [dateText(p.paidAt??p.createdAt),p.email,planNames[p.planCode],state,money(p.amount),money(p.refunded),p.note]){const td=document.createElement('td');td.textContent=v;tr.append(td);}return tr;}));if(!data.payments.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=7;td.textContent='과거 결제 이력이 없습니다';tr.append(td);$('#payment-rows').append(tr);}$('#customer-refunds').replaceChildren(...data.refunds.map(r=>{const p=document.createElement('p');p.className='fine';p.textContent=dateText(r.refundedAt)+' · 환불 '+money(r.amount)+' · '+r.reason+' · '+r.actor;return p;}));$('#customer-audit').replaceChildren(...data.audit.map(a=>{const p=document.createElement('p');p.className='fine';p.textContent=dateText(a.createdAt)+' · '+a.actor+' · '+({'profile-updated':'이용정보 수정','manual-payment-recorded':'수납 기록 추가','manual-refund-recorded':'환불 기록 추가'}[a.action]??a.action);return p;}));
const select=$('#refund-form').elements.paymentId;select.replaceChildren(...data.payments.filter(p=>p.status==='paid'&&p.refunded<p.amount).map(p=>{const o=document.createElement('option');o.value=p.id;o.dataset.balance=p.amount-p.refunded;o.textContent=dateText(p.paidAt)+' · 남은 환불 가능 '+money(p.amount-p.refunded);return o;}));if(!select.options.length){const o=document.createElement('option');o.value='';o.textContent='환불 가능한 결제가 없습니다';select.append(o);}select.dispatchEvent(new Event('change'));$('#payment-form').elements.paidAt.value=kstInput();$('#refund-form').elements.refundedAt.value=kstInput();}
$('#customer-search').onsubmit=e=>{e.preventDefault();customerPage=1;customers().catch(e=>notice(e.message));};$('#customer-prev').onclick=()=>{customerPage--;customers().catch(e=>notice(e.message));};$('#customer-next').onclick=()=>{customerPage++;customers().catch(e=>notice(e.message));};$('#close-customer').onclick=closeCustomerDrawer;
$('#profile-form').onsubmit=async e=>{e.preventDefault();if(!selectedCustomer)return;const form=e.target,button=form.querySelector('button'),c=selectedCustomer;button.disabled=true;try{await api('/api/admin/customers/'+c.id+'/profile','PATCH',{planCode:form.elements.planCode.value||null,startsAt:inputTime(form.elements.startsAt.value),expiresAt:inputTime(form.elements.expiresAt.value),note:form.elements.note.value,status:form.elements.status.value,revision:c.revision});if(selectedCustomer?.id===c.id)await loadCustomer(c.id);await customers();notice('고객 DB 정보를 저장했습니다 실제 VPN 키·결제는 변경하지 않았습니다');}catch(error){notice(error.message);}finally{button.disabled=false;}};
$('#payment-form').elements.planCode.onchange=e=>{$('#payment-form').elements.amount.value=({30:12000,90:30000,180:54000})[e.target.value];};$('#payment-form').elements.status.onchange=e=>{const field=$('#payment-form').elements.paidAt;field.disabled=e.target.value!=='paid';field.required=e.target.value==='paid';if(field.required&&!field.value)field.value=kstInput();};$('#payment-form').elements.status.dispatchEvent(new Event('change'));
$('#payment-form').onsubmit=async e=>{e.preventDefault();if(!selectedCustomer)return;const id=selectedCustomer.id,form=e.target,button=form.querySelector('button');button.disabled=true;try{paymentRequestKey??=crypto.randomUUID();await api('/api/admin/customers/'+id+'/payments','POST',{planCode:form.elements.planCode.value,amount:Number(form.elements.amount.value),status:form.elements.status.value,paidAt:form.elements.status.value==='paid'?inputTime(form.elements.paidAt.value):null,note:form.elements.note.value,requestKey:paymentRequestKey});paymentRequestKey=null;if(selectedCustomer?.id===id)await loadCustomer(id);await loadRevenue();notice('가상 수납 기록을 저장했습니다 실제 결제·이용기간 연장은 실행하지 않았습니다');}catch(error){notice(error.message);}finally{button.disabled=false;}};
$('#refund-form').elements.paymentId.onchange=e=>{const balance=e.target.selectedOptions[0]?.dataset.balance;$('#refund-form').elements.amount.max=balance??10000000;};$('#refund-form').onsubmit=async e=>{e.preventDefault();if(!selectedCustomer)return;const id=selectedCustomer.id,form=e.target,button=form.querySelector('button');button.disabled=true;try{if(!form.elements.paymentId.value)throw Error('환불 가능한 완료 결제를 선택해 주세요');refundRequestKey??=crypto.randomUUID();await api('/api/admin/payments/'+form.elements.paymentId.value+'/refunds','POST',{amount:Number(form.elements.amount.value),refundedAt:inputTime(form.elements.refundedAt.value),reason:form.elements.reason.value,requestKey:refundRequestKey});refundRequestKey=null;if(selectedCustomer?.id===id)await loadCustomer(id);await loadRevenue();notice('가상 환불 기록을 저장했습니다 실제 환불은 실행하지 않았습니다');}catch(error){notice(error.message);}finally{button.disabled=false;}};
const todayKst=kstInput().slice(0,10);$('#revenue-start').value=todayKst.slice(0,8)+'01';$('#revenue-end').value=todayKst;
async function loadRevenue(){const seq=++revenueSeq;const query=new URLSearchParams({start:$('#revenue-start').value,end:$('#revenue-end').value,group:$('#revenue-group').value});const data=await api('/api/admin/revenue?'+query);if(!csrf||seq!==revenueSeq)return;summaryCards('revenue-summary',[['결제액',money(data.totals.gross)],['환불액',money(data.totals.refunded)],['순매출',money(data.totals.net)],['완료 결제',data.totals.count+'건']]);const max=Math.max(1,...data.rows.map(r=>r.gross));$('#revenue-rows').replaceChildren(...data.rows.map(r=>{const tr=document.createElement('tr');for(const v of [r.period,r.count+'건',money(r.gross),money(r.refunded),money(r.net)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}const td=document.createElement('td'),meter=document.createElement('meter');meter.min=0;meter.max=max;meter.value=r.gross;meter.setAttribute('aria-label',r.period+' 결제액 '+money(r.gross));td.append(meter);tr.append(td);return tr;}));}$('#revenue-filter').onsubmit=e=>{e.preventDefault();loadRevenue().catch(error=>notice(error.message));};
